vim.cmd("highlight clear")
if vim.fn.exists("syntax_on") == 1 then
  vim.cmd("syntax reset")
end

vim.g.colors_name = "oled"

local colors = {
  bg = "#000000",
  sunken = "#000000",
  surface = "#161616",
  border = "#242424",
  border_strong = "#484848",
  fg = "#FFFFFF",
  fg_sec = "#999999",
  fg_dis = "#838383",
  accent = "#22D3EE",
  accent_soft = "#242424",
  cyan = "#34E2E2",
