  warning = "#FCE94F",
  keyword = "#AD7FA8",
  func = "#FFFFFF",
  str = "#8AE234",
  type = "#729FCF",
  num = "#FCE94F",
  comment = "#838383",
  op = "#D5D5D5",
}

